export function escapeHtml(text: string): string {
  return text.replaceAll("<", "&lt;").replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;").replaceAll("'", "&#39;").replaceAll("&", "&amp;");
}
import test from "node:test";
import assert from "node:assert/strict";
import * as core0 from "../src/crlf_line_position.ts";
test("crlf-line-position",()=>{assert.deepEqual(core0.lineColumn("ab\nc",4),{line:1,column:1});});
import * as core1 from "../src/html_text_escaping.ts";
test("html-text-escaping",()=>{assert.equal(core1.escapeHtml("hello"),"hello");});
import * as core2 from "../src/literal_replace_all.ts";
import * as api2 from "../src/literal_replace_all_api.ts";
test("literal-replace-all",()=>{assert.deepEqual(api2.replaceBatch([{text:"abc",needle:"b",replacement:"X"}]),[{before:"abc",after:"aXc",changed:true}]);});
import * as core3 from "../src/whitespace_word_spans.ts";
import * as api3 from "../src/whitespace_word_spans_api.ts";
test("whitespace-word-spans",()=>{assert.deepEqual(api3.wordsForSelection("hello world").map(span=>span.text),["hello","world"]);});
import * as core4 from "../src/inclusive_clamp.ts";
test("inclusive-clamp",()=>{assert.equal(core4.clamp(5,0,10),5);});
